// Clone returns an independent copy of the stream at the same bar: the two
// evolve separately and share only the [Core].
func (sp *FRAMAStream) Clone() *FRAMAStream {
	cl := *sp
	cl.cb_slot_sufHigh = append(sp.cb_slot_sufHigh[:0:0], sp.cb_slot_sufHigh...)
	cl.cb_slot_sufLow = append(sp.cb_slot_sufLow[:0:0], sp.cb_slot_sufLow...)
	cl.cb_slot_oldHigh = append(sp.cb_slot_oldHigh[:0:0], sp.cb_slot_oldHigh...)
	cl.cb_slot_oldLow = append(sp.cb_slot_oldLow[:0:0], sp.cb_slot_oldLow...)
	return &cl
}

